92	    pub(crate) fn policy(&self) -> serde_json::Map<String, serde_json::Value> {
93	        let mut policy = serde_json::Map::new();
94	        policy.insert(
95	            OSV_POLICY_KEY.to_string(),
96	            serde_json::Value::String(self.fingerprint.clone()),
97	        );
98	        policy
99	    }
