101	    pub(crate) fn can_trust_policy(
102	        &self,
103	        policy: &serde_json::Map<String, serde_json::Value>,
104	    ) -> bool {
105	        policy.get(OSV_POLICY_KEY).and_then(serde_json::Value::as_str)
