109	    pub(crate) fn vulnerability_ids(&self, name: &str, version: &str) -> Vec<String> {
110	        let Some(advisories) = self.packages.get(normalized_name(name).as_ref()) else {
111	            return Vec::new();
112	        };
113	        // Parse the candidate once and share it across every advisory's
114	        // range check; exact-version advisories never need the parse.
115	        let parsed = Version::parse(version).ok();
116	        let mut seen = HashSet::new();
117	        advisories
118	            .iter()
119	            .filter(|advisory| advisory.affects(version, parsed.as_ref()))
120	            // A single OSV record can list the same package in several
121	            // `affected` blocks; dedup so one advisory id isn't repeated.
122	            .filter(|advisory| seen.insert(advisory.id.as_str()))
123	            .map(|advisory| advisory.id.clone())
124	            .collect()
125	    }
126	
127	    fn decision(&self, name: &str, version: &str) -> PackageVersionGuardDecision {
128	        let ids = self.vulnerability_ids(name, version);
129	        if ids.is_empty() {
130	            return PackageVersionGuardDecision::Allow;
131	        }
132	        PackageVersionGuardDecision::Reject {
133	            reason: format!(
134	                "is listed in the local OSV database as vulnerable ({})",
135	                format_advisory_ids(&ids),
136	            ),
137	        }
138	    }
139	}
