[metadata] {"filePath": "/workspace/repo/pnpr/crates/pnpr/src/server.rs", "oldString": "/// Parse the on-disk packument, rewrite `dist.tarball` URLs, and
/// build the response. When `abbreviated` is true, strip down to", "newString": "/// Remove from a parsed packument every version that must not be served
/// when the local OSV database is enabled, keeping the document
/// internally consistent:
///
/// * versions the OSV database flags as vulnerable;
/// * versions whose key is not a valid semver string (can't be validated
///   against the database, so treated as ineligible);
/// * versions whose entry's `version` field disagrees with its key (an
///   identity mismatch — the entry can't be trusted to be what its key
///   claims).
///
/// The matching `time` entries are dropped, and any `dist-tags` pointing
/// at a removed version are dropped too, so a served packument never
/// advertises a version it no longer carries. Applied at serve time, so
/// a freshly proxied response and a later cache hit filter identically.
fn filter_packument_versions(
    packument: &mut Value,
    package: &str,
    osv: &crate::resolver::OsvIndex,
) {
    let Some(obj) = packument.as_object_mut() else { return };
    let removed: std::collections::HashSet<String> =
        match obj.get("versions").and_then(Value::as_object) {
            Some(versions) => versions
                .iter()
                .filter(|(key, entry)| version_is_ineligible(key, entry, package, osv))
                .map(|(key, _)| key.clone())
                .collect(),
            None => return,
        };
    if removed.is_empty() {
        return;
    }
    if let Some(versions) = obj.get_mut("versions").and_then(Value::as_object_mut) {
        versions.retain(|key, _| !removed.contains(key));
    }
    if let Some(time) = obj.get_mut("time").and_then(Value::as_object_mut) {
        time.retain(|key, _| !removed.contains(key));
    }
    if let Some(tags) = obj.get_mut("dist-tags").and_then(Value::as_object_mut) {
        tags.retain(|_, target| target.as_str().is_none_or(|v| !removed.contains(v)));
    }
}

/// Whether one `versions` entry must be dropped from a served packument
/// (see [`filter_packument_versions`] for the three criteria).
fn version_is_ineligible(
    key: &str,
    entry: &Value,
    package: &str,
    osv: &crate::resolver::OsvIndex,
) -> bool {
    if node_semver::Version::parse(key).is_err() {
        return true;
    }
    if entry.get("version").and_then(Value::as_str) != Some(key) {
        return true;
    }
    osv.is_vulnerable(package, key)
}

