fn osv_dir() -> TempDir {
    let dir = TempDir::new().unwrap();
    std::fs::write(
        dir.path().join("GHSA-foo.json"),
        r#"{"id":"GHSA-foo","affected":[{"package":{"ecosystem":"npm","name":"foo"},"versions":["1.0.0"]}]}"#,
    )
    .unwrap();
    dir
}

fn config_for(upstream: &str, storage: std::path::PathBuf, osv_path: std::path::PathBuf) -> Config {
    let listen = SocketAddr::V4(SocketAddrV4::new(Ipv4Addr::LOCALHOST, 4873));
    let mut config = Config::proxy(listen, storage);
    config.uplinks.get_mut("npmjs").unwrap().url = upstream.to_string();
    config.public_url = "http://example.test".to_string();
    config.osv.enabled = true;
    config.osv.path = Some(osv_path);
    config
}

async fn body_bytes(body: Body) -> Vec<u8> {
    to_bytes(body, usize::MAX).await.unwrap().to_vec()
}

#[tokio::test]
async fn packument_filters_vulnerable_versions() {
    let mut upstream = mockito::Server::new_async().await;
    let packument = json!({
        "name": "foo",
        "dist-tags": { "latest": "1.0.0", "safe": "1.1.0" },
        "versions": {
            "1.0.0": { "name": "foo", "version": "1.0.0", "dist": { "tarball": format!("{}/foo/-/foo-1.0.0.tgz", upstream.url()) } },
            "1.1.0": { "name": "foo", "version": "1.1.0", "dist": { "tarball": format!("{}/foo/-/foo-1.1.0.tgz", upstream.url()) } },
            "bad": { "name": "foo", "version": "9.9.9", "dist": {} }
        },
        "time": { "1.0.0": "2020-01-01T00:00:00.000Z", "1.1.0": "2020-01-02T00:00:00.000Z", "bad": "x" }
    });
    let m = upstream.mock("GET", "/foo").with_status(200).with_body(packument.to_string()).expect(1).create_async().await;

    let tmp = TempDir::new().unwrap();
    let osv = osv_dir();
    let app = router(config_for(&upstream.url(), tmp.path().to_path_buf(), osv.path().to_path_buf()));

    let r = app.clone().oneshot(Request::get("/foo").body(Body::empty()).unwrap()).await.unwrap();
    assert_eq!(r.status(), StatusCode::OK);
    let body: Value = serde_json::from_slice(&body_bytes(r.into_body()).await).unwrap();
    assert!(body["versions"].get("1.0.0").is_none(), "vulnerable removed");
    assert!(body["versions"].get("1.1.0").is_some(), "safe kept");
    assert!(body["versions"].get("bad").is_none(), "identity mismatch removed");
    assert!(body["time"].get("1.0.0").is_none());
    assert!(body["dist-tags"].get("latest").is_none(), "tag to removed version dropped");
    assert_eq!(body["dist-tags"]["safe"], "1.1.0");

    // Second request served from cache filters identically.
    let r2 = app.clone().oneshot(Request::get("/foo").body(Body::empty()).unwrap()).await.unwrap();
    let body2: Value = serde_json::from_slice(&body_bytes(r2.into_body()).await).unwrap();
    assert!(body2["versions"].get("1.0.0").is_none());

    // version manifest 404 for removed version
    let mr = app.clone().oneshot(Request::get("/foo/1.0.0").body(Body::empty()).unwrap()).await.unwrap();
    assert_eq!(mr.status(), StatusCode::NOT_FOUND);
    let mr2 = app.clone().oneshot(Request::get("/foo/1.1.0").body(Body::empty()).unwrap()).await.unwrap();
    assert_eq!(mr2.status(), StatusCode::OK);

    // dist-tags endpoint
    let dt = app.clone().oneshot(Request::get("/-/package/foo/dist-tags").body(Body::empty()).unwrap()).await.unwrap();
    let dtb: Value = serde_json::from_slice(&body_bytes(dt.into_body()).await).unwrap();
    assert!(dtb.get("latest").is_none());
    assert_eq!(dtb["safe"], "1.1.0");

    m.assert_async().await;
}

